import React from "react";
import { useNavigate } from "react-router-dom";

const CourseSelector = () => {
  const navigate = useNavigate();

  const selectCourse = (course) => {
    const name = localStorage.getItem("currentStudent");
    if (!name) {
      alert("Please login first!");
      return;
    }

    localStorage.setItem("selectedCourse", course);

    if (course === "3-5") navigate("/game-3-5");
    else if (course === "6-8") navigate("/game-6-8");
    else if (course === "9-15") navigate("/game-9-15");
  };

  return (
    <div className="min-h-screen bg-blue-100 p-8 flex flex-col items-center justify-center text-center">
      <h1 className="text-3xl font-bold text-blue-800 mb-6">📚 Select Your Course</h1>
      <div className="grid gap-6 md:grid-cols-3">
        <button
          onClick={() => selectCourse("9-15")}
          className="bg-yellow-200 hover:bg-yellow-300 px-6 py-4 rounded-xl shadow-lg text-xl font-semibold"
        >
          🧠 9–15 Years
        </button>
        <button
          onClick={() => selectCourse("6-8")}
          className="bg-green-200 hover:bg-green-300 px-6 py-4 rounded-xl shadow-lg text-xl font-semibold"
        >
          🧩 6–8 Years
        </button>
        <button
          onClick={() => selectCourse("3-5")}
          className="bg-pink-200 hover:bg-pink-300 px-6 py-4 rounded-xl shadow-lg text-xl font-semibold"
        >
          🎨 3–5 Years
        </button>
      </div>
    </div>
  );
};

export default CourseSelector;
